 mp=ROOT/'generated/measured/measurements.json.gz';m,c=verify_measurement(mp);a=read(ASSUMPTIONS);out=SURFACE/'generated';master=gzread(out/'master.json.gz');fit=gzread(out/'fitted_depth_and_fold_traces.json.gz');t=time.monotonic();compiled=compile_master(master,{'pitch':a['pitch_m']},max_candidate_cells=c['compile']['max_candidates'],max_output_cells=c['compile']['max_cells']);render=make_render_data(compiled);elapsed=time.monotonic()-t;gzwrite(out/'compiled.cells.json.gz',compiled);gzwrite(out/'region.render.json.gz',render)
