 report={'source_sha256':m['source_sha256'],'measurement_sha256':sha(mp),'assumptions_sha256':sha(ASSUMPTIONS),'generator_sha256':sha(ROOT/'tools/regularized_surface.py'),'validator_sha256':sha(__file__),'same_measurement_same_surface_master':repeated==master,'same_measurement_same_depth_fit':refit==fit,'independent_common_compile_exact':repeat==compiled,'independent_mesh_exact':make_render_data(repeat)==render,'common_compile':{'cells':len(compiled['cells']),'quads':render['quad_count'],'candidate_cells':compiled['candidate_cells'],'wall_seconds':elapsed,'max_rss_mib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024,'compiler_sha256':compiled['compiler_source_hash']},'depth_prior':{'side_bounds_violation_m':fit['bounds_violation_m'],'thickness_m':a['normal_thickness_m'],'recovered_real_fabric_thickness':False,'depth_is_inferred':True,'true_fold_depth_unknown':True},'structure':topology,'front_back_conflict_policy':a['constraints'],'before_hull_projection_metrics':before,'after_surface_projection_metrics':metrics,'local_pixel_regression':{'source_pixels_changed':1738,'changed_source_geometry_rows':rows,'only_expected_source_rows_changed':bool(rows) and set(rows)<=set(range(548,560)),'depth_solution_unchanged':fit['f_row_centers_m']==mutfit['f_row_centers_m'],'changed_operations':len(changed),'changed_occupancy_cells':len(diff),'cell_center_y_m':[min(ys),max(ys)] if ys else None,'projection':reprojection},'art_approved':False,'GPU_reviewed':False,'source_unchanged':sha(m['source_path'])==c['source_sha256']}
