 sheet=Image.new('RGB',(1560,1100),'white');d=ImageDraw.Draw(sheet);d.text((20,15),'r10 SURFACE01 | MEASURED PIXELS + EXPLICIT MINIMUM-BENDING DEPTH PRIOR',fill='black');d.text((20,40),'Same ROI, all front patches retained. Actual 25mm normal thickness / 25mm common grid. No fragment deletion.',fill='black')
 for i,(name,img) in enumerate(zip(['front','side','back'],overlays)):
  sheet.paste(img,(20+i*515,80));d.text((20+i*515,270),name+(' | patch IoU %.3f'%metrics[name]['panel_union_IoU'] if name=='front' else ' | identity UNKNOWN; support residual only'),fill='black')
 for i,img in enumerate(views):sheet.paste(img,(10+i*388,310))
 old=Image.open(ROOT/'generated/region/cpu_three_quarter.png');old.thumbnail((230,230));sheet.paste(old,(20,740));d.text((20,980),'Previous filled feasibility volume',fill='black')
 lines=[f'After: {len(compiled["cells"])} cells, {render["quad_count"]} quads. 6-connected components: {topology["six_connected_components"]}; sizes {topology["sizes"][:8]}.',f'Front IoU before {before["front"]["panel_union_IoU"]:.3f} -> after {metrics["front"]["panel_union_IoU"]:.3f}. Back contradictions remain visible, not erased.','Depth is the bounded minimum-bending hypothesis, NOT recovered fold depth or a measured fabric thickness.',f'Local PNG mutation changes {len(rows)} source rows / {len(diff)} occupancy cells; depth prior unchanged.','Unknown labels were retained in both versions; the earlier loss came from hard back-silhouette intersection.','True panel pairing, attachment and hidden folds remain unresolved. Source skin/costume reference unchanged.','CPU evidence only. No full-character expansion, art approval, GPU/rig/socket or new AI image.']
 for i,line in enumerate(lines):d.text((280,755+i*33),line,fill='black')
